#!/bin/bash
# Plan A: collapse-aware mixing with n-gram entropy PI controller
# Usage: bash run_plan_a.sh [extra args for controlled_pipeline.py]
# Override defaults via env vars: MODE=threshold SEED=0 bash run_plan_a.sh

set -euo pipefail

MODE=${MODE:-pi_controller}
SEED=${SEED:-42}
GENERATIONS=${GENERATIONS:-5}
TOKENS_PER_GEN=${TOKENS_PER_GEN:-20000000}
CKPT_INTERVAL=${CKPT_INTERVAL:-5000000}
OUTPUT_DIR=${OUTPUT_DIR:-/root/autodl-tmp/plan_a_${MODE}_seed${SEED}}
W_FIXED=${W_FIXED:-0.5}
THRESHOLD=${THRESHOLD:-5.5}
KP=${KP:-0.15}
KI=${KI:-0.02}
U_BIAS=${U_BIAS:-0.5}
SETPOINT_MARGIN=${SETPOINT_MARGIN:-0.9}
W_MIN=${W_MIN:-0.1}
W_MAX=${W_MAX:-0.9}

source /root/miniconda3/etc/profile.d/conda.sh && conda activate base

cd /root/collapse-aware-mixing

python3 -u controlled_pipeline.py \
    --mode $MODE \
    --seed $SEED \
    --num_generations $GENERATIONS \
    --tokens_per_generation $TOKENS_PER_GEN \
    --checkpoint_interval_tokens $CKPT_INTERVAL \
    --output_dir $OUTPUT_DIR \
    --w_fixed $W_FIXED \
    --threshold $THRESHOLD \
    --kp $KP \
    --ki $KI \
    --u_bias $U_BIAS \
    --setpoint_margin $SETPOINT_MARGIN \
    --w_min $W_MIN \
    --w_max $W_MAX \
    --no_wandb \
    "$@"
RUNSH_EOF
chmod +x /root/collapse-aware-mixing/run_plan_a.sh
echo "run_plan_a.sh written OK"

